count = 0
for k, v in data["cache"].items():
    if isinstance(v, str) and v in fixes:
        data["cache"][k] = fixes[v]
        count += 1

with open("hiragana_data.json", "w", encoding="utf-8") as f:
    json.dump(data, f, ensure_ascii=False, indent=4)
print(f"Fixed {count} entries by matching VALUE.")
